def _t():
    ba = bytearray(b'A' * 1024)
    mv = memoryview(ba)

    class S(bytes):

        def __len__(self):
            mv.release()
            ba.clear()
            return 1
    try:
        mv.hex(*(S(b':'),))
    except BufferError:
        pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

